local disp_single = { ['or'] = '%s %s or %s %s', ['sqbr'] = '%s %s [%s %s]', ['comma'] = '%s %s, %s %s', ['default'] = '%s %s (%s %s)', }
local disp_double = { ['or'] = '%s%s%s %s or %s%s%s %s', ['sqbr'] = '%s%s%s %s [%s%s%s %s]', ['comma'] = '%s%s%s %s, %s%s%s %s', ['default'] = '%s%s%s %s (%s%s%s %s)', }
local function process(parms) local cvt = converter(parms) local outext = cvtround(parms.value, parms, cvt) local outext2 = cvtround(parms.value2, parms, cvt) local intext = parms.in_text local intext2 = parms.in_text2 local range = parms.range local disp = parms.disp local wikitext if range == nil then wikitext = disp_single[disp] or disp_single['default'] wikitext = wikitext:format(intext, parms.in_unit, outext, parms.out_unit) else wikitext = disp_double[disp] or disp_double['default'] wikitext = wikitext:format(intext, range[1], intext2, parms.in_unit, outext, range[2], outext2, parms.out_unit) end return wikitext end
